INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0012-000000000000', 'MongoDB란 무엇이며 전통적인 SQL 데이터베이스와 무엇이 다른가요?', 'EASY', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000001', 'MongoDB가 NoSQL로 분류되는 이유는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000002', '문서 지향 데이터베이스란 무엇인지 설명해 주세요.', 'EASY', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000003', 'MongoDB에서 컬렉션(Collection)은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000004', 'MongoDB의 BSON 포맷은 무엇을 의미하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000005', '몽고DB에서 스키마리스(schema-less) 데이터베이스란 무슨 뜻인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000006', '몽고DB의 장점은 무엇이고, 단점은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000007', '수평적 확장(horizontal scaling) 측면에서 MongoDB는 어떤 이점이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000008', 'MongoDB에서 인덱스(Index)는 어떻게 동작하고 어떤 효과가 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000009', 'MongoDB에서 데이터 일관성을 유지하기 위한 방법은 무엇인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000000A', 'MongoDB에서 데이터 중복을 허용하는 상황에서는 어떤 문제가 발생할 수 있나요?', 'HARD',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000000B', 'MongoDB에서 복합 인덱스(Composite Index)란 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000000C', '몽고DB의 CRUD 연산에는 어떤 것들이 있나요?', 'EASY',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000000D', '예를 들어 MongoDB에서 데이터 조회를 하는 db.find() 사용법을 아나요?', 'EASY',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000000E', '업데이트 연산자(예: $set, $inc 등)의 사용 방법을 아나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000000F', 'MongoDB의 집계 프레임워크(Aggregation)란 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000010', '$match, $group 등의 집계 파이프라인 단계에 대해 아나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000011', 'Map-Reduce를 MongoDB에서 사용하는 경우는 언제인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000012', 'MongoDB에서 트랜잭션을 지원하나요? (지원한다면 어떤 범위에서?)', 'HARD',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000013', '몽고DB의 레플리카 세트(Replica Set)란 무엇이고 왜 사용하는가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000014', '레플리카 세트의 Primary와 Secondary 노드 역할은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000015', 'Automatic Failover는 MongoDB에서 어떻게 동작하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000016', '샤딩(Sharding)이란 무엇이며, MongoDB에서 어떻게 구현되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000017', '샤드 키(Shard Key)를 선택할 때 고려해야 할 사항은 무엇인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000018', 'MongoDB에서 조인(join)이 직접 지원되지 않는 이유는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-000000000019', '임베디드 문서와 참조(DBRef) 중 어느 것을 언제 사용하면 좋나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000001A', 'MongoDB의 GridFS는 무엇을 위한 기능인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000001B', '몽고DB와 MySQL을 성능 측면에서 비교해 본다면 어떤 차이가 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000001C', '백업과 복원은 MongoDB에서 어떻게 수행하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000012'),
('b0000000-0000-0000-0012-00000000001D', 'mongodump와 mongoexport의 차이는 무엇인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000012');
